@spec tuning_spec  src=tests/specs/tuning_spec.lua  loc=637  cases=43
@exercises tuning (tuning)
@surface   tuning.derive, tuning.stepToParts, tuning.stepToMidi, tuning.midiToStep, tuning.scalaPitch, tuning.unrooted, tuning.removeStep, tuning.sortSteps, tuning.midiName, tuning.parseScalaFile, tuning.parseScalaPitches, tuning.scalaToTemper, tuning.genEqual, tuning.edoDegrees, tuning.degreesToSpec, tuning.genHarmonics, tuning.genSubharmonics, tuning.parseChord, tuning.genChord, tuning.genCPS, tuning.genRank2, tuning.nextMosSize, tuning.mosInfo

# Intent
  Pins tuning.lua's pure display + derivation layer: the Option-B nameless
  step labels, the derived octaveStep / cellWidth fields, and the coordinate
  conversions between MIDI and step-octave. Realisation invariants (I1-I5)
  live in tm_tuning_spec; projection wiring in view_context_spec.

# Helpers
  @fn nameless(cents)  @ 10-12
  @fn stepText(temper, step, octave)  @ 16-19
      -- The two label parts joined, so a case that is about the whole label can
      -- assert it as one string.
  @fn rooted(root)  @ 22-28
      -- A 12EDO scale with the root fields the case is about; everything else default.
  @fn authored(root)  @ 32-37
      -- The same 12EDO in the shape a step edit sees: pitch tokens, names densified
      -- to '' as cloneForEdit leaves them, so sortSteps and removeStep can drive it.
  @fn soundsA415(temper, step, why)  @ 45-49
      -- What the rooted step sounds, as (midi, detune); the deletions and sorts below
      -- all claim to leave it alone.

# Cases
  @case 'preset EDOs derive width 3 and a past-the-end octaveStep'  [pure]  @ 53-63
  @case 'named step renders name + octave'  [pure]  @ 67-72
  @case 'a negative octave renders as its magnitude and reports the sign'  [pure]  @ 76-85
  @case 'the octaveStep bump owns the sign: a step that crosses zero is not negative'  [pure]  @ 89-96
  @case 'nameless step falls back to degree-octave with a dash'  [pure]  @ 100-108
  @case 'nameless scale past 9 steps widens the cell for 2-digit degrees'  [pure]  @ 112-119
  @case 'sub-octave period widens the octave field for 2-digit octaves'  [pure]  @ 123-132
  @case 'a root numbering the octaves near zero narrows the field'  [pure]  @ 136-156
  @case 'a root numbering the range low makes the bottom end the wider'  [pure]  @ 160-172
  @case 'derive recomputes width when names are dropped'  [pure]  @ 176-184
  @case 'partially named scale: named steps keep their label, blanks fall back'  [pure]  @ 188-195
  @case 'scalaPitch parses ratios, cents, bare integers and n\\m steps'  [pure]  @ 199-213
  @case 'derive compiles pitches → cents and periodPitch → period'  [pure]  @ 217-225
  @case 'derive reduces an authored root to rootCents + octaveBase'  [pure]  @ 229-239
  @case 'a preset states no root and derives the default (0,0) = (1,-1)'  [pure]  @ 243-252
  @case 'unrooted is the library form: the four dropped, the stamps back at the default'  [pure]  @ 256-267
  @case 'a deleted step takes the root\'s index down with it'  [pure]  @ 271-281
  @case 'deleting the rooted step restates the root on the unison'  [pure]  @ 285-302
  @case 'a step sorted below the root carries the root\'s index'  [pure]  @ 306-315
  @case 'retuning the rooted step moves the scale, not the root'  [pure]  @ 319-332
  @case 'a temper stating no root comes through both edits unstamped'  [pure]  @ 336-347
  @case 'midiName spells a pitch in the untempered twelve names'  [pure]  @ 351-357
  @case 'the default root reduces the conversions to MIDI-relative arithmetic'  [pure]  @ 361-376
  @case 'a flattened root moves every pitch by its offset and renames nothing'  [pure]  @ 380-402
  @case 'an octave-shifted root renames every octave and moves no pitch'  [pure]  @ 406-422
  @case 'the conversions invert each other at every root'  [pure]  @ 426-439
  @case 'EDO presets carry n\\m source tokens that derive back to their cents'  [pure]  @ 443-450
  @case 'parseScalaFile strips comments, description and count; returns pitch tokens'  [pure]  @ 454-462
  @case 'parseScalaPitches keeps every non-comment, non-blank line'  [pure]  @ 466-471
  @case 'scalaToTemper prepends the unison, splits the period, flags periodAsStep'  [pure]  @ 475-486
  @case 'scalaToTemper sorts unordered pitches ascending; widest becomes the period'  [pure]  @ 490-499
  @case 'scalaToTemper rejects an unparseable token'  [pure]  @ 503-508
  @case 'genEqual: full EDO and a diatonic subset, base implicit, period last'  [pure]  @ 512-524
  @case 'edoDegrees: relative cumulates, absolute sorts; non-octave equave suffixes'  [pure]  @ 528-536
  @case 'degreesToSpec round-trips edoDegrees in both modes'  [pure]  @ 540-544
  @case 'genHarmonics / genSubharmonics: rooted on the low harmonic, top is period'  [pure]  @ 548-557
  @case 'genChord: otonal vs inverted, last member is the period'  [pure]  @ 561-573
  @case 'parseChord rejects fewer than two notes or non-integers'  [pure]  @ 577-581
  @case 'genCPS: hexany rooted on the smallest product, 1/1 first, ascending'  [pure]  @ 585-591
  @case 'genRank2: pure-fifth size 7 / up 5 is Pythagorean major, 1/1 first'  [pure]  @ 595-601
  @case 'genRank2: size 4 / up 2 matches the Scale Workshop worked example'  [pure]  @ 605-610
  @case 'genRank2: irrational (EDO-step) generator emits cents tokens'  [pure]  @ 614-619
  @case 'nextMosSize / mosInfo: pure-fifth ladder 2->3->5->7->12; 7 is 5L 2s'  [pure]  @ 623-635

